do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='438dfb9a-0c9c-5634-80a1-b03be34a2453'; if prior is not null then if not prior @> '{"id":"438dfb9a-0c9c-5634-80a1-b03be34a2453","leaf_id":"0bfe0962-b793-56a3-8c14-ec66ee229f6f","source_id":"bf2f46e2-5343-5f3c-8dc2-7ad1ab1091e2","logical_id":"438dfb9a-0c9c-5634-80a1-b03be34a2453","version":1,"origin":"OFFICIAL","state":"DRAFT","body":"빗변 h=√(x²+x⁻²), 내접반지름 r=(x+1/x−h)/2, 외접반지름 R=h/2. 유리화하면 r=1/(x+1/x+h)이므로 rR→1/4, 넓이의 곱 π²r²R²→π²/16.\n접선 쌍 사이의 거리는 각각 2√(a²m+b²)/√(1+m), 2√(a²+b²m)/√(1+m). 곱을 제곱해 미분하면 16(a²−b²)²(1−m)/(1+m)³이다. m=0에서도 연속이며 m=1에서 최대 4(a²+b²)².\nAB 중점 M=(2,−1), G=(3,−1)이므로 PM=2PG. 완전제곱하면 중심 (10/3,−1), 반지름 2/3인 원이다. 직선 AC는 3x−y−16=0, 밑변 길이 √10. 최대 높이는 5/√10+2/3, 최대 넓이 5/2+√10/3."}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,logical_id,version,origin,state,body) values ('438dfb9a-0c9c-5634-80a1-b03be34a2453','0bfe0962-b793-56a3-8c14-ec66ee229f6f','bf2f46e2-5343-5f3c-8dc2-7ad1ab1091e2','438dfb9a-0c9c-5634-80a1-b03be34a2453',1,'OFFICIAL','DRAFT','빗변 h=√(x²+x⁻²), 내접반지름 r=(x+1/x−h)/2, 외접반지름 R=h/2. 유리화하면 r=1/(x+1/x+h)이므로 rR→1/4, 넓이의 곱 π²r²R²→π²/16.
접선 쌍 사이의 거리는 각각 2√(a²m+b²)/√(1+m), 2√(a²+b²m)/√(1+m). 곱을 제곱해 미분하면 16(a²−b²)²(1−m)/(1+m)³이다. m=0에서도 연속이며 m=1에서 최대 4(a²+b²)².
AB 중점 M=(2,−1), G=(3,−1)이므로 PM=2PG. 완전제곱하면 중심 (10/3,−1), 반지름 2/3인 원이다. 직선 AC는 3x−y−16=0, 밑변 길이 √10. 최대 높이는 5/√10+2/3, 최대 넓이 5/2+√10/3.'); end if; end $row$;
