do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='da894369-e322-5922-af8a-f3cbd120f3a9'; if prior is not null then if not prior @> '{"id":"da894369-e322-5922-af8a-f3cbd120f3a9","leaf_id":"25d468bf-5b14-5cc6-bb39-1f62f564bb09","source_id":"34c4411e-5c28-55cf-a927-ce41fab2abb5","logical_id":"da894369-e322-5922-af8a-f3cbd120f3a9","version":1,"origin":"OFFICIAL","state":"DRAFT","body":"0<a<1이면 a^(2n)을 묶어 나머지 log(1+a^(3n))/n→0, 극한은 2log a. a=1이면 log 2/n→0. a>1이면 a^(5n)을 묶어 5log a.\n양변 로그를 취하면 ln n/n≤ln k/k. f(x)=ln x/x는 x≥3에서 도함수 (1−ln x)/x²가 음수이다. 따라서 3≤k≤n, a_n=n−2이며 극한은 1.\n두 교점 (x,±y)의 접선은 ±yY=2p(X+x), A=(−x,0). 두 벡터의 내적으로 cos60°=(4x²−y²)/(4x²+y²)=(x−p)/(x+p), 따라서 x=3p. 타원에 y²=4px를 넣고 b²=a²−p²를 이용해 양의 근 x=a(a−p)/(a+p). t=a/p>1로 두면 t²−4t−3=0, t=2+√7."}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,logical_id,version,origin,state,body) values ('da894369-e322-5922-af8a-f3cbd120f3a9','25d468bf-5b14-5cc6-bb39-1f62f564bb09','34c4411e-5c28-55cf-a927-ce41fab2abb5','da894369-e322-5922-af8a-f3cbd120f3a9',1,'OFFICIAL','DRAFT','0<a<1이면 a^(2n)을 묶어 나머지 log(1+a^(3n))/n→0, 극한은 2log a. a=1이면 log 2/n→0. a>1이면 a^(5n)을 묶어 5log a.
양변 로그를 취하면 ln n/n≤ln k/k. f(x)=ln x/x는 x≥3에서 도함수 (1−ln x)/x²가 음수이다. 따라서 3≤k≤n, a_n=n−2이며 극한은 1.
두 교점 (x,±y)의 접선은 ±yY=2p(X+x), A=(−x,0). 두 벡터의 내적으로 cos60°=(4x²−y²)/(4x²+y²)=(x−p)/(x+p), 따라서 x=3p. 타원에 y²=4px를 넣고 b²=a²−p²를 이용해 양의 근 x=a(a−p)/(a+p). t=a/p>1로 두면 t²−4t−3=0, t=2+√7.'); end if; end $row$;
